-- Historical schema only; never used by application startup.
CREATE TABLE "documents"(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,content TEXT NOT NULL,chapter TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, category TEXT NOT NULL DEFAULT 'personal', original_name TEXT, stored_name TEXT, file_size INTEGER, file_type TEXT, course_id INTEGER REFERENCES courses(id) DEFAULT 1, chapter_id INTEGER REFERENCES chapters(id), owner_id INTEGER REFERENCES users(id), published INTEGER NOT NULL DEFAULT 0, sha256 TEXT, summary TEXT NOT NULL DEFAULT '', source_title TEXT NOT NULL DEFAULT '', source_url TEXT NOT NULL DEFAULT '', deleted_at TEXT, published_at TEXT);
CREATE TABLE conversations(id INTEGER PRIMARY KEY AUTOINCREMENT,material_id INTEGER,question TEXT NOT NULL,answer TEXT NOT NULL,model TEXT NOT NULL,mode TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, user_id INTEGER REFERENCES users(id));
CREATE TABLE chapters(id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, course_id INTEGER REFERENCES courses(id) DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1, textbook_number INTEGER, pdf_start INTEGER, pdf_end INTEGER, archived_at TEXT);
CREATE TABLE "knowledge_points"(id INTEGER PRIMARY KEY, chapter_id INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, lab_path TEXT, published INTEGER NOT NULL DEFAULT 1, digital_managed INTEGER NOT NULL DEFAULT 0, draft_revision_id INTEGER, published_revision_id INTEGER, edit_version INTEGER NOT NULL DEFAULT 0, archived_at TEXT);
CREATE TABLE questions(id INTEGER PRIMARY KEY, chapter_id INTEGER NOT NULL, prompt TEXT NOT NULL, options TEXT NOT NULL, answer INTEGER NOT NULL, explanation TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1, kind TEXT NOT NULL DEFAULT 'single', answer_data TEXT, items TEXT NOT NULL DEFAULT '[]', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE schema_versions(version INTEGER PRIMARY KEY);
CREATE TABLE users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('teacher','student')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, is_admin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf_token TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE courses(id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0,is_demo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE document_knowledge_points(document_id INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,knowledge_point_id INTEGER NOT NULL REFERENCES knowledge_points(id) ON DELETE CASCADE,PRIMARY KEY(document_id,knowledge_point_id));
CREATE TABLE document_versions(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES documents(id),stored_name TEXT NOT NULL,original_name TEXT NOT NULL,file_size INTEGER NOT NULL,file_type TEXT NOT NULL,sha256 TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE account_audit(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),target_id INTEGER REFERENCES users(id),action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sections(id INTEGER PRIMARY KEY,chapter_id INTEGER NOT NULL REFERENCES chapters(id),code TEXT NOT NULL DEFAULT '',title TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,published INTEGER NOT NULL DEFAULT 0);
CREATE TABLE knowledge_revisions(id INTEGER PRIMARY KEY,point_id INTEGER NOT NULL REFERENCES knowledge_points(id),body TEXT NOT NULL,author_id INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE content_events(id INTEGER PRIMARY KEY,point_id INTEGER NOT NULL REFERENCES knowledge_points(id),actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,revision_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE knowledge_assets(id INTEGER PRIMARY KEY,stored_name TEXT NOT NULL UNIQUE,original_name TEXT NOT NULL,mime TEXT NOT NULL,file_size INTEGER NOT NULL,sha256 TEXT NOT NULL,uploader_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE revision_assets(revision_id INTEGER NOT NULL REFERENCES knowledge_revisions(id),asset_id INTEGER NOT NULL REFERENCES knowledge_assets(id),PRIMARY KEY(revision_id,asset_id));
CREATE TABLE knowledge_progress(user_id INTEGER NOT NULL REFERENCES users(id),point_id INTEGER NOT NULL REFERENCES knowledge_points(id),revision_id INTEGER NOT NULL DEFAULT 0,read_done INTEGER NOT NULL DEFAULT 0,self_assessed INTEGER NOT NULL DEFAULT 0,position TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',bookmarked INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,point_id,revision_id));
CREATE TABLE interaction_runs(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),point_id INTEGER NOT NULL REFERENCES knowledge_points(id),revision_id INTEGER NOT NULL,block_id TEXT NOT NULL,engine_version INTEGER NOT NULL DEFAULT 1,trace TEXT NOT NULL,completed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE question_knowledge(question_id INTEGER NOT NULL REFERENCES questions(id),point_id INTEGER NOT NULL REFERENCES knowledge_points(id),PRIMARY KEY(question_id,point_id));
CREATE TABLE study_attempts(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),point_id INTEGER REFERENCES knowledge_points(id),revision_id INTEGER NOT NULL DEFAULT 0,request_key TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key));
CREATE TABLE learning_feedback(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),point_id INTEGER NOT NULL REFERENCES knowledge_points(id),revision_id INTEGER NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE experiments(id INTEGER PRIMARY KEY,title TEXT NOT NULL,draft_revision_id INTEGER,published_revision_id INTEGER,edit_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE experiment_revisions(id INTEGER PRIMARY KEY,experiment_id INTEGER NOT NULL REFERENCES experiments(id),body TEXT NOT NULL,author_id INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE experiment_previews(user_id INTEGER NOT NULL REFERENCES users(id),revision_id INTEGER NOT NULL REFERENCES experiment_revisions(id),PRIMARY KEY(user_id,revision_id));
CREATE TABLE experiment_runs(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),experiment_id INTEGER NOT NULL REFERENCES experiments(id),revision_id INTEGER NOT NULL REFERENCES experiment_revisions(id),engine_version TEXT NOT NULL,input_json TEXT NOT NULL,result_json TEXT NOT NULL,observation TEXT NOT NULL DEFAULT '',completed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_question_jobs(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,request_hash TEXT NOT NULL,config_json TEXT NOT NULL,sources_json TEXT NOT NULL,model TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',warnings_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key));
CREATE TABLE ai_question_drafts(id INTEGER PRIMARY KEY,job_id INTEGER NOT NULL REFERENCES ai_question_jobs(id),body_json TEXT NOT NULL,source_ref TEXT NOT NULL,source_quote TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',version INTEGER NOT NULL DEFAULT 0,question_id INTEGER REFERENCES questions(id));
CREATE TABLE ai_lesson_jobs(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,request_hash TEXT NOT NULL,config_json TEXT NOT NULL,sources_json TEXT NOT NULL,model TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',body_json TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 0,imported_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key));
CREATE TABLE document_ai_indexes(document_id INTEGER PRIMARY KEY REFERENCES documents(id),signature TEXT NOT NULL,body_json TEXT NOT NULL);
CREATE TABLE personal_ai_jobs(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),chapter_id INTEGER NOT NULL REFERENCES chapters(id),kind TEXT NOT NULL,parent_id INTEGER REFERENCES personal_ai_jobs(id),request_key TEXT NOT NULL,request_hash TEXT NOT NULL,config_json TEXT NOT NULL,sources_json TEXT NOT NULL,body_json TEXT NOT NULL DEFAULT '{}',model TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',bookmarked INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key));
CREATE TABLE personal_ai_attempts(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),job_id INTEGER NOT NULL REFERENCES personal_ai_jobs(id),request_key TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key));
CREATE TABLE chapter_content_imports(id INTEGER PRIMARY KEY,course_id INTEGER NOT NULL REFERENCES courses(id),chapter_id INTEGER NOT NULL REFERENCES chapters(id),package_id TEXT NOT NULL,package_hash TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),result_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(course_id,package_id));
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX document_owner ON documents(owner_id,category);
CREATE INDEX knowledge_chapter ON knowledge_points(chapter_id);
CREATE INDEX documents_visibility ON documents(category,deleted_at,published,chapter_id);
CREATE INDEX conversations_owner ON conversations(user_id,id);
CREATE INDEX knowledge_revisions_point ON knowledge_revisions(point_id,id);
CREATE INDEX experiment_run_owner ON experiment_runs(user_id,id);
CREATE INDEX experiment_revision_parent ON experiment_revisions(experiment_id,id);
CREATE UNIQUE INDEX ai_question_one_running ON ai_question_jobs(user_id) WHERE status='running';
CREATE INDEX ai_question_owner ON ai_question_jobs(user_id,id);
CREATE UNIQUE INDEX ai_lesson_one_running ON ai_lesson_jobs(user_id) WHERE status='running';
CREATE UNIQUE INDEX personal_ai_one_running ON personal_ai_jobs(user_id) WHERE status='running';
CREATE VIEW materials AS SELECT * FROM documents;
CREATE VIEW knowledge AS SELECT * FROM knowledge_points;